export const C=343,SAMPLE_RATE=24000,SOUND_WATER=1500;
const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
const smooth=x=>{x=clamp(x,0,1);return x*x*(3-2*x)};
let sourceLevels;
function rand(seed){let x=seed>>>0;return()=>{x^=x<<13;x^=x>>>17;x^=x<<5;return (x>>>0)/2147483648-1}}
export function roomReverbTime(length,width,height,absorption){const volume=length*width*height,surface=2*(length*width+length*height+width*height),alpha=clamp(absorption,.05,.85);return clamp(.161*volume/(surface*alpha),.12,5)}
export function thorpAbsorption(fHz){const f=Math.max(.001,fHz/1000),f2=f*f;return .11*f2/(1+f2)+44*f2/(4100+f2)+2.75e-4*f2+.003}
export function echoImpulses({length=18,width=12,height=5,absorption=.22},maxOrder=2){const sx=length*.22,sy=width*.42,sz=height*.42,rx=length*.73,ry=width*.58,rz=height*.42,events=[];for(let i=-maxOrder;i<=maxOrder;i++)for(let j=-maxOrder;j<=maxOrder;j++)for(let k=-maxOrder;k<=maxOrder;k++){const ix=2*i*length+(i%2?length-sx:sx),iy=2*j*width+(j%2?width-sy:sy),iz=2*k*height+(k%2?height-sz:sz),d=Math.hypot(ix-rx,iy-ry,iz-rz),order=Math.abs(i)+Math.abs(j)+Math.abs(k);if(d<1e-8)continue;events.push({distance:d,delay:d/343,gain:Math.pow(1-absorption,order)*Math.min(1,Math.hypot(sx-rx,sy-ry,sz-rz)/d)})}return events.sort((a,b)=>a.delay-b.delay)}
export function solveEmission(t,m,h){const a=1-m*m,b=h/C;if(Math.abs(a)<1e-10)return t>0?[(t*t-b*b)/(2*t)]:[];const d2=m*m*t*t+a*b*b;if(d2<0||(m>1&&t<=0))return[];const d=Math.sqrt(d2),q=t+(t<0?-d:d),roots=q===0?[(t-d)/a,(t+d)/a]:[q/a,(t*t-b*b)/q];return roots.filter((x,i)=>Number.isFinite(x)&&x<=t+1e-9&&Math.abs(x+Math.hypot(m*x,b)-t)<1e-7&&(!i||Math.abs(x-roots[0])>1e-8)).sort((x,y)=>x-y)}
export function makeBuffer(length,sr=SAMPLE_RATE,channels=1){const n=Math.max(1,Math.ceil(length*sr));return channels===1?new Float32Array(n):[new Float32Array(n),new Float32Array(n)]}
function summarize(kind,samples,sr,extra={}){const channels=Array.isArray(samples)?samples:[samples],n=channels[0].length;let peak=0,sum=0;for(const ch of channels)for(let i=0;i<n;i++){ch[i]=Math.tanh(ch[i]*.75);peak=Math.max(peak,Math.abs(ch[i]));sum+=ch[i]*ch[i]}return {kind,samples:channels[0],...(channels.length>1?{samplesL:channels[0],samplesR:channels[1]}:{}),sampleRate:sr,duration:n/sr,peak,rms:Math.sqrt(sum/(n*channels.length)),...extra}}
function sourceTone(t,type,f){if(type==='race')return .48*Math.sin(2*Math.PI*f*t)+.18*Math.sin(2*Math.PI*f*2.03*t)+.08*Math.sin(2*Math.PI*f*3.71*t);if(type==='train')return .32*Math.sin(2*Math.PI*f*t)+.28*Math.sin(2*Math.PI*f*1.26*t)+.2*Math.sin(2*Math.PI*f*1.51*t);const phase=2*Math.PI*(f*t+48*Math.sin(2*Math.PI*.42*t));return .32*Math.sin(phase)+.18*Math.sin(phase*1.47)}
function renderDoppler(c,sr){const dur=9,n=Math.ceil(dur*sr),out=[new Float32Array(n),new Float32Array(n)],v=c.speed/3.6,m=v/C,h=c.height,f=c.source==='train'?160:c.source==='siren'?360:c.pitch,base=-3;let lastPitch=0;for(let i=0;i<n;i++){const t=base+i/sr,roots=solveEmission(t,m,h);let l=0,r=0;for(const tau of roots){const range=Math.hypot(v*tau,h),ratio=1/Math.abs(1+m*m*tau/Math.hypot(m*tau,h/C)),x=v*tau,pan=clamp(.5+.5*x/range,0,1),sp=sourceTone(tau,c.source,f),amp=sp*Math.min(1,18/range)/(roots.length>1?1.4:1);l+=amp*Math.sqrt(1-pan);r+=amp*Math.sqrt(pan);if(t===0)lastPitch=f*ratio}out[0][i]=l;out[1][i]=r}return summarize('doppler',out,sr,{start:base,pitch:lastPitch||f,note:'The source moves at constant speed; sound is resampled at solved retarded times and panned from its arriving direction.',axis:'AUDIO AMPLITUDE · RELATIVE',model:'RETARDED TIME · SPHERICAL SPREADING'})}
function renderEcho(c,sr){const rt60=roomReverbTime(c.length,c.width,c.height,c.absorption),impulses=echoImpulses(c),dur=Math.min(6,Math.max(.8,rt60*1.35+.15)),n=Math.ceil(dur*sr),noise=rand(8317),excLen=Math.floor(sr*.12),exc=new Float32Array(excLen);let lp=0;for(let i=0;i<excLen;i++){const t=i/sr,raw=noise(),a=1-Math.exp(-2*Math.PI*1800/sr);lp+=a*(raw-lp);const env=Math.exp(-t/.032);exc[i]=(c.source==='clap'?raw*.8+lp*.4:c.source==='wood'?lp*.9+Math.sin(2*Math.PI*115*t)*Math.exp(-t/.055):Math.sin(2*Math.PI*185*t)*Math.exp(-t/.035)+.25*Math.sin(2*Math.PI*370*t)*Math.exp(-t/.045))*env}const out=new Float32Array(n),direct=impulses[0]?.distance??2,used=[];for(const e of impulses){if(e.delay>dur)continue;const index=Math.floor(e.delay*sr),amp=.55*e.gain;used.push({delay:e.delay,gain:amp,order:Math.round(Math.log(Math.max(e.gain,1e-8))/Math.log(Math.max(1-c.absorption,1e-4)))});for(let j=0;j<exc.length&&index+j<n;j++)out[index+j]+=exc[j]*amp*(direct/Math.max(1,e.distance))}const alpha=1-Math.exp(-2*Math.PI*1100/sr);lp=0;for(let i=0;i<n;i++){const late=noise();lp+=alpha*(late-lp);const t=i/sr;out[i]+=lp*.045*Math.exp(-6.91*t/Math.max(.1,rt60))}return summarize('echo',out,sr,{rt60,impulses:used,note:`A shoebox image-source estimate with a diffuse decaying tail. Calculated RT₆₀: ${rt60.toFixed(2)} s.`,axis:'AMPLITUDE · RELATIVE',model:'IMAGE-SOURCE EARLY ECHOES · SABINE RT₆₀'})}
export function underwaterLoss(distanceKm,fHz){return thorpAbsorption(fHz)*distanceKm}
function renderUnderwater(c,sr){const dist=c.distance,delay=dist*1000/SOUND_WATER,sourceDur=1.65,dur=delay+sourceDur+.22,n=Math.ceil(dur*sr),out=new Float32Array(n),start=Math.round(delay*sr),type=c.source,noise=rand(9182),freqs=Array.from({length:32},(_,i)=>40*Math.pow(100, i/31)),attenuation=freqs.map(f=>({frequency:f,dbKm:thorpAbsorption(f)}));let pingFilter=0;for(let i=0;i<Math.round(sourceDur*sr);i++){const t=i/sr,env=Math.sin(Math.PI*Math.min(1,t/sourceDur))**.55;let p=0;if(type==='whale'){const f=75+95*t/sourceDur,phase=2*Math.PI*(75*t+95*t*t/(2*sourceDur));p=.58*Math.sin(phase)+.15*Math.sin(2*phase)+.06*Math.sin(3*phase)}else if(type==='ping'){const f=800+4400*smooth(t/.08),phase=2*Math.PI*(800*t+(4400-800)*t*t/(2*.08));p=(t<.9?.65*Math.sin(phase):0)}else{p=.28*Math.sin(2*Math.PI*68*t)+.19*Math.sin(2*Math.PI*104*t)+.1*Math.sin(2*Math.PI*153*t)+.09*noise()}let atten=0,weight=0;for(let k=1;k<=5;k++){const f=type==='whale'?90*k:type==='ping'?1800*k:65*k,a=Math.pow(10,-thorpAbsorption(f)*dist/20);weight+=1/k;atten+=a/k}atten/=weight;const j=start+i;if(j<n)out[j]=p*env*atten*(type==='ping'?1:1.7)}return summarize('underwater',out,sr,{arrival:delay,range:dist,attenuation,note:`${SOUND_WATER} m/s in seawater; frequency-dependent loss uses the Thorp empirical absorption formula. Sound pressure level and ocean refraction are not predicted.`,axis:'ABSORPTION · dB/km',model:'THORP SEAWATER ABSORPTION · IDEALIZED PATH'})}
function renderBeats(c,sr){const dur=5,n=dur*sr,out=new Float32Array(n),f1=c.f1,f2=f1+c.beat,d=c.spacing,x=c.position*d*.45,y=1.3,r1=Math.hypot(x+d/2,y),r2=Math.hypot(x-d/2,y),p1=2*Math.PI*f1*r1/C,p2=2*Math.PI*f2*r2/C;for(let i=0;i<n;i++){const t=i/sr,env=smooth(t/.04)*smooth((dur-t)/.08);out[i]=.29*env*(Math.sin(2*Math.PI*f1*(t-r1/C))+Math.sin(2*Math.PI*f2*(t-r2/C)))}return summarize('beats',out,sr,{f1,f2,beat:Math.abs(f2-f1),pathDifference:r1-r2,note:`Two stationary sine sources at ${f1} Hz and ${f2} Hz. Their pressure waves are summed at a fixed listener.`,axis:'SUMMED PRESSURE · RELATIVE',model:'TWO-TONE SUPERPOSITION · SOUND SPEED 343 m/s'})}
function renderThunder(c,sr){const dist=c.distance*1000,arrival=dist/C,rumbleDuration=clamp(c.storm/C,.35,8),dur=arrival+rumbleDuration+.5,n=Math.ceil(dur*sr),out=new Float32Array(n),noise=rand(280320+Math.round(c.distance*10)),cutoff=clamp(1550/(1+c.distance*.38),250,1500),alpha=1-Math.exp(-2*Math.PI*cutoff/sr);let lp=0;for(let i=0;i<n;i++){const t=i/sr-arrival;if(t<0)continue;const raw=noise();lp+=alpha*(raw-lp);const attack=smooth(t/.012),body=Math.exp(-t/(.38+c.storm/C*.58)),rumble=.35*Math.exp(-t/(.7+c.storm/C*1.1))*noise();out[i]=(.72*lp*body+rumble)*attack/Math.sqrt(Math.max(.5,c.distance))}return summarize('thunder',out,sr,{arrival,rumbleDuration,sourceTime:0,note:`Arrival delay is distance divided by ${C} m/s. The rolling source is a stylized storm-width noise model, not a field recording.`,axis:'PRESSURE · RELATIVE',model:'SOUND-TRAVEL DELAY · STYLIZED THUNDER ROLL'})}
function polyblep(t,dt){if(t<dt){t/=dt;return t+t-t*t-1}if(t>1-dt){t=(t-1)/dt;return t*t+t+t+1}return 0}
function oscillator(phase,wave,dt){if(wave==='sine')return Math.sin(phase*2*Math.PI);if(wave==='triangle')return 1-4*Math.abs(phase-.5);if(wave==='square')return (phase<.5?1:-1)+polyblep(phase,dt)-polyblep((phase+.5)%1,dt);return 2*phase-1-polyblep(phase,dt)}
function renderDesigner(c,sr){const dur=2.5,n=Math.round(dur*sr),out=new Float32Array(n),f=c.frequency,dt=f/sr,attack=c.attack/1000,decay=c.decay/1000,fc=clamp(c.cutoff,30,sr*.48),alpha=1-Math.exp(-2*Math.PI*fc/sr),noise=rand(1001);let lp=0;for(let i=0;i<n;i++){const t=i/sr,phase=(t*f)%1,env=t<attack?smooth(t/Math.max(.001,attack))*Math.exp(-t/Math.max(.02,decay)):Math.exp(-(t-attack)*5/Math.max(.02,decay)),raw=c.wave==='noise'?noise():oscillator(phase,c.wave,dt);lp+=alpha*(raw-lp);out[i]=.42*lp*env}return summarize('designer',out,sr,{frequency:f,note:'A band-limited oscillator feeds a one-pole low-pass filter and an attack-decay envelope.',axis:'AMPLITUDE · RELATIVE',model:'POLYBLEP OSCILLATOR · LOW-PASS FILTER'})}
export function renderExperiment(kind,config,sr=SAMPLE_RATE){if(!config||typeof config!=='object')throw Error('Missing experiment settings');let d={...config};switch(kind){case'doppler':if(!(d.speed>=20&&d.speed<=300&&d.height>=5&&d.height<=250))throw Error('Pass speed or height is outside the model range.');return renderDoppler(d,sr);case'echo':if(!(d.length>=5&&d.length<=60&&d.width>=3&&d.width<=35&&d.height>=2.5&&d.height<=15&&d.absorption>=.05&&d.absorption<=.85))throw Error('Room settings are outside the model range.');return renderEcho(d,sr);case'underwater':if(!(d.distance>=.1&&d.distance<=10&&d.depth>=20&&d.depth<=4000))throw Error('Ocean settings are outside the model range.');return renderUnderwater(d,sr);case'beats':if(!(d.f1>=100&&d.f1<=800&&d.beat>=0&&d.beat<=30&&d.spacing>=.2&&d.spacing<=8&&d.position>=-1&&d.position<=1))throw Error('Tone or source settings are outside the model range.');return renderBeats(d,sr);case'thunder':if(!(d.distance>=.5&&d.distance<=10&&d.storm>=100&&d.storm<=3000))throw Error('Storm settings are outside the model range.');return renderThunder(d,sr);case'designer':if(!['sine','triangle','square','sawtooth','noise'].includes(d.wave)||!(d.frequency>=40&&d.frequency<=1200&&d.cutoff>=150&&d.cutoff<=10000&&d.attack>=2&&d.attack<=600&&d.decay>=40&&d.decay<=1800))throw Error('Patch settings are outside the model range.');return renderDesigner(d,sr);default:throw Error('Unknown sound experiment.')}}
